//oc:errors std
//oc:mcp {"include":true,"order":17,"name":"refocus_member","description":"Refocus a member's context (online-only, else 409). Answers with a bounded receipt (``id``), not the roster row — call ``get_member`` when you need the rest.","legacy":{"descriptor":"{\n      \"description\": \"Refocus a member's context (online-only, else 409). Answers with a bounded receipt (``id``), not the roster row \\u2014 call ``get_member`` when you need the rest.\",\n      \"inputSchema\": {\n        \"properties\": {\n          \"member_id\": {\n            \"type\": \"string\"\n          }\n        },\n        \"required\": [\n          \"member_id\"\n        ],\n        \"additionalProperties\": false,\n        \"type\": \"object\"\n      },\n      \"name\": \"refocus_member\"\n    }"}}
